const engine = require('src/priority_engine');
const queue = engine.generateQueue();
return [{ json: { tasks: queue.tasks.slice(0, 3), generated_at: queue.generated_at } }];

const router = require('src/router');
const task = items[0].json.tasks[0];
const route = router.route(task.id, task.name, task.type);
return [{ json: route }];

const guard = require('src/agentguard');
const guard = new guard.Agentguard();
const approved = guard.approveTask(items[0].json.estimated_cost);
return [{ json: { ...items[0].json, approved } }];

const executor = require('src/executor');
const e = new executor.Executor();
const result = e.executeTask(items[0].json.task_id, items[0].json.task_name, items[0].json.command, items[0].json.complexity);
return [{ json: result }];

const pipeline = require('src/secure_t_pipeline');
const p = new pipeline.SecureTPipeline();
const result = p.run(items[0].json.task_id, items[0].json.repo_url);
return [{ json: result }];

const validator = require('src/validator');
const v = new validator.Validator();
const report = v.validate(items[0].json.task_id, items[0].json.output, items[0].json.type);
return [{ json: report }];

const monitor = require('src/monitor');
const m = new monitor.Monitor();
const report = m.runChecks();
return [{ json: report }];
